import pandas as pd
CSVQA_FRAMES = {t["table_id"]: pd.DataFrame([r["values"] for r in t["records"]], columns=t["columns"], index=[r["source_row"] for r in t["records"]]) for t in CSVQA_DATA["tables"]}
import gurobipy as gp
from gurobipy import GRB

def solve_problem():
    import pandas as pd
    df = CSVQA_FRAMES['file_0_view_0']
    zz_mask = df['SKU'].str.casefold().str.startswith('zz')
    zz_df = df.loc[zz_mask].copy()
    I = list(zz_df['SKU'])
    if len(set(I)) != len(I):
        raise ValueError("Duplicate SKUs found in 'ZZ' subset; SKUs must be unique.")
    try:
        r_i = zz_df.set_index('SKU')['Revenue'].astype(float).to_dict()
        d_i = zz_df.set_index('SKU')['Demand'].astype(float).to_dict()
        s_i = zz_df.set_index('SKU')['Initial Inventory'].astype(float).to_dict()
    except Exception as e:
        raise ValueError(f'Error converting parameters to float: {e}')
    ub_i = {sku: int(min(d_i[sku], s_i[sku])) for sku in I}
    m = gp.Model('ZZ_Product_Fulfillment')
    m.Params.MIPGap = 0.0001
    quantity_vars = m.addVars(I, lb=0, ub=[ub_i[sku] for sku in I], vtype=GRB.INTEGER, name='')
    m.setObjective(gp.quicksum((r_i[sku] * quantity_vars[sku] for sku in I)), GRB.MAXIMIZE)
    m.optimize()
    return m
m = solve_problem()